  "exports.subtitleStart": "ڈاؤن لوڈ ہمیشہ صرف ایہناں تیکر محدود ہوندے نیں",
  "exports.subtitleRest": "۔ ہر فائل اتے کاروبار دا ناں تے اوہ تاریخ لکھی ہوندی ہے جدوں اوہ بنائی گئی سی۔",
  "exports.createBusinessFirst": "پہلاں کوئی کاروبار بناؤ — برآمداں کسے کاروبار دیاں ہوندیاں نیں، ایپ دیاں نہیں۔",
  "exports.lockedTitle": "CSV تے Excel برآمداں Business دی خاصیت ہے",
  "exports.lockedDesc": "تہاڈا ورک سپیس Essentials پلان اتے ہے۔ Business وچ CSV تے Excel برآمداں، سٹاک دی قیمت، بے حد پروڈکٹ تے عملہ، سپلائر، خریداری تے بنڈل شامل ہوندے نیں۔",
  "exports.seeBusiness": "ویکھو Business وچ کی کی شامل ہے",
  "exports.whatTheseAre": "ایہ فائلاں کی نیں",
  "exports.about1": "ہر ڈیٹا سیٹ CSV یا اصل Excel ورک بک (.xlsx) وچ آؤندا ہے — پوری انوینٹری ورک بک صرف Excel وچ ہے، ہر ڈیٹا سیٹ لئی اک شیٹ۔ CSV فائلاں Excel، Numbers، Google Sheets تے زیادہ تر سٹاک ایپاں وچ کھلدیاں نیں۔ UTF-8 لکھت، کوٹاں وچ کامے، نوٹاں وچ لائن بریک تے کوڈاں وچ شروع والے صفر سب محفوظ رہندے نیں، تے جہڑے سیل فارمولے ورگے شروع ہون اوہناں نوں بے اثر کر دتا جاندا ہے تاں جو سپریڈشیٹ اوہناں نوں لکھت سمجھ کے کھولھے۔",
  "exports.about2": "Excel فائلاں وچ SKU، UPC، ISBN تے بارکوڈ لکھت والے سیل ہوندے نیں — کدے وی سائنسی نشانی نہیں تے کدے وی صفر کٹے نہیں جاندے — کالماں دی چوڑائی، ہیڈر فلٹر تے کرنسی یا مقدار دے فارمیٹ لاگو ہوندے نیں۔ پوری انوینٹری ورک بک پروڈکٹاں، سٹاک دی سطح، تھاواں تے نقل و حرکت نوں وکھ وکھ شیٹاں اتے رکھدی ہے۔",
  "exports.about3": "بہت وڈیاں برآمداں ہر ڈیٹا سیٹ لئی 20,000 قطاراں اتے رک جاندیاں نیں — جدوں ایہہ ہووے تے فائل دا ناں ایہہ دسدا ہے (truncated-20000)، تاں جو ادھوری فائل کدے وی پوری نہ سمجھی جاوے۔",
  "exports.about4": "بیک اپ تہاڈے ڈیٹے دی اک جھلک ہے، اک کلک نال بحالی نہیں۔ اوہنوں بحال کرنا دستی، پہلاں جائزہ لین والا کم ہے، اس لئی فائل نوں محفوظ رکھو — ایپ وچ اجے کوئی چیز حذف شدہ کاروبار نوں ایہدے توں دوبارہ نہیں بنا سکدی۔ ایپ کوڈ تے Base44 پلیٹ فارم دے بیک اپ ایہناں فائلاں توں وکھ سنبھالے جاندے نیں۔",
  "exports.about5": "فوٹواں تے منسلکات اوہناں دے محفوظ لنکاں وچ درج ہوندے نیں — تصویر فائلاں آپ ڈاؤن لوڈ وچ نہیں پائیاں جاندیاں۔",
  "exports.backupTitle": "پورا بیک اپ",
  "exports.backupDesc": "اک فائل جہدے وچ ایس کاروبار دے پروڈکٹ، تھاواں، سٹاک دی سطح، پورا نقل و حرکت دا کھاتہ، سپلائر، خریداری، آرڈر، واپسیاں، گنتیاں تے لسٹاں — نال اوہدی پروفائل سیٹنگ وی۔ ایہنوں کسے ایسی جگہ رکھو جہڑی تہاڈے قابو وچ ہووے۔",
