  "settings.cancelTerms.intro": "ایہہ ادا شدہ Luminous StockHaven سبسکرپشناں لئی شرائط نیں۔ ویب سائٹ سبسکرپشن بلنگ Stripe راہیں ہوندی اے۔ تسی تھلے دتے سبسکرپشن منسوخ کرو بٹن نال کسی ویلے وی اپنی سبسکرپشن خود منسوخ کر سکدے او — کسے سٹاف دی منظوری دی لوڑ نہیں۔ منسوخی تے رقم واپسی دیاں درخواستاں سرکاری کسٹمر سپورٹ رابطے theluminousbookshop@outlook.com راہیں وی نمٹائیاں جا سکدیاں نیں۔",
  "settings.cancelTerms.noApprovalBody": "تسی کسی ویلے وی اپنی سبسکرپشن خود منسوخ کر سکدے او۔ کسے سٹاف دی منظوری دی لوڑ نہیں۔ مستقبل دی تجدید صرف اودوں رکدی اے جدوں بلنگ فراہم کرن والا منسوخی دی تصدیق کرے۔",
  "settings.cancelTerms.noApprovalTitle": "بغیر منظوری دے منسوخ کرو:",
  "settings.cancelTerms.paymentBody": "ادا شدہ آزمائشاں لئی، ست دن دی آزمائش لئی سائن اپ ویلے ادائیگی دا طریقہ چاہیدا اے۔ جے لاگو آزمائش منسوخی دی آخری تریخ دے اندر منسوخ نہ کیتی گئی، تے چنیا گیا ماہانہ پلان آزمائش توں بعد خودکار طور اُتے چارج ہووے گا۔ قیمت، پہلی بلنگ دی تریخ، تے فراہم کرن والے لئی مخصوص منسوخی دی آخری تریخ سائن اپ ویلے دکھائی جانی چاہیدی اے۔ آزمائشی بلنگ Stripe راہیں ہوندی اے۔",
  "settings.cancelTerms.paymentTitle": "ادائیگی دا طریقہ تے خودکار تجدید:",
  "settings.cancelTerms.remainingBody": "جے تسی پہلاں ہی اک بلنگ مدت لئی ادائیگی کر چکے او، تے تسی اوس تصدیق شدہ ادائیگی دی تریخ تک رسائی رکھ سکدے او۔ پہلاں ختم کرن لئی مناسب فراہم کرن والے دی تصدیق تے کوئی لاگو رقم واپسی دا عمل چاہیدا اے۔ مفت آزمائش دی رسائی فراہم کرن والے ولوں تصدیق شدہ آزمائش ختم ہون دی تریخ دے مطابق ختم ہوندی اے۔",
  "settings.cancelTerms.remainingTitle": "باقی رسائی:",
  "settings.cancelTerms.storesBody": "جے تسی کدے Google Play یا Apple App Store راہیں سبسکرائب کرو، تے تہاڈی سبسکرپشن اوس سٹور ولوں بل تے منظم کیتی جاندی اے۔ تہانوں اوہنوں سیدھا اوسی Google یا Apple اکاؤنٹ دے سبسکرپشن والے حصے وچ منسوخ کرنا پے سکدا اے جس نال سبسکرائب کیتا گیا سی۔ وکھری ویب سائٹ سبسکرپشن منسوخ کرنا، ایس ایپ نوں ان انسٹال کرنا، یا Luminous StockHaven اکاؤنٹ حذف کرن دی درخواست کرنا سٹور ولوں بل کیتی سبسکرپشن نوں خودکار طور اُتے منسوخ نہیں کردا۔ اپنی خرید دی رسید ویکھ کے تصدیق کرو کہ تہانوں بل کون کردا اے۔",
  "settings.cancelTerms.storesTitle": "Google Play تے Apple App Store سبسکرپشناں (جے تسی کدے سٹور راہیں سبسکرائب کرو):",
