  "settings.trial.cancelKeeps": "آزمائش دے دوران منسوخ کرن نال تہاڈے پورے 7 دن رہندے نیں — رسائی {date} نوں ختم ہوندی اے، تے تہانوں چارج نہیں کیتا جاوے گا۔",
  "staff.access.noSeatBody": "تہاڈے اکاؤنٹ کول ایس کاروبار لئی کوئی سٹاف سیٹ نہیں، اس لئی اوہدا سٹاک بند رہندا اے۔ مالک نوں آکھو کہ تہانوں سٹاف تے کرداراں وچ شامل کرے۔",
  "staff.access.noSeatTitle": "ایہہ کاروبار تہاڈے لاگ ان لئی کھلا نہیں",
  "staff.access.pendingBody": "ایس کاروبار کول تہاڈی ای میل لئی اک دعوت اے جو اجے فعال نہیں ہوئی۔ مالک نوں آکھو کہ تہاڈی سٹاف حالت فعال کرے۔ اودوں تک ایتھے کجھ نظر نہیں آوے گا۔",
  "staff.access.pendingTitle": "تہاڈی دعوت اجے فعال نہیں",
  "staff.access.signOut": "سائن آؤٹ کرو",
  "staff.access.suspendedBody": "اک منتظم نے فعال کاروبار لئی ایس سٹاف اکاؤنٹ نوں معطل کر دتا اے۔ اوہناں نوں آکھو کہ تہانوں واپس فعال کرن، فیر دوبارہ سائن ان کرو۔",
  "staff.access.suspendedTitle": "تہاڈی رسائی روکی گئی اے",
  "staff.addFirst": "پہلا سٹاف ممبر شامل کرو",
  "staff.addMember": "سٹاف ممبر شامل کرو",
  "staff.emptyBody": "اک بندہ شامل کرو، اوہنوں اک کردار تے اوہدے نال جان والیاں اجازتاں دیو، تے اوہنوں ایس کاروبار وچ سائن ان کرن لئی ای میل راہیں دعوت دتی جاندی اے۔",
  "staff.emptyTitle": "اجے کوئی سٹاف نہیں",
  "staff.eyebrow": "ٹیم",
  "staff.how.p1": "ہر ممبر دا اک کردار تے اوہدی اپنی اجازتاں دی لسٹ ہوندی اے، اس لئی تسی اک کردار توں شروع کر سکدے او تے نواں کردار بنائے بغیر اک چیز بدل سکدے او۔ کردار نوں تبدیل کرن نال اوہدے اُتے پہلاں توں موجود ممبر دوبارہ نہیں لکھے جاندے — اوہناں دے کردار دیاں ڈیفالٹ قدراں دوبارہ لاگو کرن لئی اک ممبر کھولو۔",
  "staff.how.p2": "پسندیدہ کردار اک Business فیچر اے: Essentials پنج بلٹ ان کردار استعمال کردا اے (مالک، مینیجر، سٹاک کلرک، سیلز کلرک، ویکھن والا)۔",
  "staff.how.p3": "دعوتاں ای میل راہیں بھیجیاں جاندیاں نیں۔ اک ممبر صرف اودوں سائن ان کر سکدا اے جدوں اوہ قبول کرے، تے کسے نوں ایس لسٹ توں ہٹان نال اوہدا ایپ اکاؤنٹ حذف نہیں ہوندا۔",
  "staff.how.p4": "اک سٹور اوہ تھاں اے جتھے اک بندہ مقرر کیتا جاندا اے۔ ایہہ اوہدے کارڈ اُتے درج ہوندا اے؛ اوہ کی کھول سکدا اے ایہہ اجے وی اوہدے کردار تے اجازتاں نال طے ہوندا اے۔",
  "staff.how.p5": "اجازتاں طے کردیاں نیں کہ ہر بندہ کی کھول سکدا اے: اوہدے کردار توں باہر دے مینو آئٹم چھپے رہندے نیں، تے اک روکیا گیا پتا صفحے دی بجائے “تہاڈے کردار اُتے نہیں” دا نوٹس دکھاندا اے۔ تبدیلی اگلی وار لاگو ہوندی اے جدوں اوہ بندہ ایپ لوڈ کرے؛ اک ممبر نوں معطل کرن نال اوہ پوری طرحاں باہر ہو جاندا اے۔",
  "staff.how.p6": "منتظمین سارا ڈیٹا ویکھ تے بدل سکدے نیں، ایپ صارفین تے کرداراں دا انتظام کر سکدے نیں، تے کدے وی سٹاف کردار نال محدود نہیں ہوندے۔ جس کول کوئی سٹاف ریکارڈ نہیں — نویں کاروبار دا مالک — اوہ پوری رسائی رکھدا اے۔",
