  "settings.security.changeEmailTitle": "اپنی اکاؤنٹ ای میل بدلو",
  "settings.security.changeEmailDesc": "اپنا اکاؤنٹ نویں ای میل ول منتقل کرو۔ تہاڈی دکان، انوینٹری، ٹیم تے تریخ اوہدے نال منتقل ہو جاندے نیں — تے کوئی نویں مفت آزمائش شروع نہیں ہوندی۔ ہر ہور سائن ان شدہ ڈیوائس سائن آؤٹ ہو جاندی اے۔",
