  "training.lessons.mgr-give-rewards.step1": "ورک فورس کھولو تے انعام تے ٹیپ کرو۔ ٹیم ممبر چنو، فیر قسم: سٹور وچ فیصد چھوٹ، گفٹ کارڈ، یا کجھ ہور جیہڑا تسی اپنے لفظاں وچ بیان کرو۔",
  "training.lessons.mgr-give-rewards.step2": "انعام نوں اک چھوٹا ناں دیو تے جے چاہو تے نوٹ۔ بندے نوں فوری گھنٹی وجدی اے، تے انعام اوہناں دے میرے انعام وچ اپنے کوڈ نال انتظار کردا اے۔",
  "training.lessons.mgr-give-rewards.step3": "حد، ڈیزائن دے مطابق: تسی صرف سٹاف نوں انعام دیندے او۔ تسی خود نوں یا کسے ہور مینیجر نوں انعام نہیں دے سکدے — مینیجر نوں انعام دینا مالک دا فیصلہ اے، تے ایپ صاف طور تے انکار کر دیوے گی۔",
  "training.lessons.mgr-give-rewards.step4": "ٹل تے، اوہ کوڈ لکھو جیہڑا ٹیم ممبر دکھاندا اے تے اوہنوں استعمال شدہ نشان لاؤ — ہر کوڈ اک واری کم کردا اے۔ جے پلان بدل جان تے تسی جیہڑا انعام دتا سی اوہنوں کالعدم کر سکدے او؛ مالک دے تحفے مالک دے نیں کالعدم کرن لئی۔",
  "training.lessons.mgr-give-rewards.title": "اپنے سٹاف نوں انعام دینا",
  "training.lessons.owner-give-rewards.step1": "انعام ورک فورس وچ، انعام ٹیب تے رہندے نیں، تے اوہ صرف Business پلان لئی نیں — Essentials تے ٹیب اک بند دروازہ دکھاندی اے، ایس لئی تہاڈی ٹیم ویکھ سکدی اے کہ وڈا پلان کی رکھدا اے۔",
  "training.lessons.owner-give-rewards.step2": "تسی ٹیم تے کسے نوں وی انعام دے سکدے او — سٹاف تے مینیجر دونے۔ بندہ چنو، فیر قسم: سٹور وچ فیصد چھوٹ (کوئی وی فیصد جیہڑا تسی چنو)، کتے وی گفٹ کارڈ، یا کوئی ترغیب جیہڑی تسی اپنے لفظاں وچ بیان کرو۔",
  "training.lessons.owner-give-rewards.step3": "انعام اپنے اک واری والے کوڈ نال پہنچدا اے تے بندے دی گھنٹی وجاندا اے۔ اوہ ٹل تے کوڈ دکھاندے نیں؛ مالک یا مینیجر اوہنوں لکھ کے استعمال شدہ نشان لاندا اے۔",
  "training.lessons.owner-give-rewards.step4": "اک چھپی یا سانجھی انعام سلپ صرف تہاڈے کاروبار دا ناں رکھدی اے — کدے ایپ دا نہیں۔ ایہہ تہاڈے سٹور دا شکریہ اے، کوئی اشتہار نہیں۔",
  "training.lessons.owner-give-rewards.title": "انعام دینا (Business پلان)",
  "training.lessons.owner-rewards-oversight.step1": "تہاڈا مینیجر وی انعام دے سکدا اے — صرف سٹاف نوں۔ ایپ مینیجر دے خود نوں یا کسے ہور مینیجر نوں انعام دین توں انکار کردی اے؛ مینیجر نوں انعام دینا ہمیشہ تہاڈا فیصلہ اے۔",
  "training.lessons.owner-rewards-oversight.step2": "تسی کاروبار وچ ہر انعام انعام دی تریخ وچ ویکھدے او: کس نے دتا، کس نوں ملیا، تے اوہ تیار، استعمال شدہ یا کالعدم اے۔ مینیجر صرف اوہ انعام ویکھدا اے جیہڑے اوہناں نے دتے تے اوہ جیہڑے اوہناں نوں ملے۔",
  "training.lessons.owner-rewards-oversight.step3": "تسی کوئی وی انعام کالعدم کر سکدے او، اوہ سمیت جیہڑا تہاڈے مینیجر نے دتا۔ مینیجر اپنے تحفے کالعدم کر سکدا اے، پر کدے تہاڈے نہیں۔",
  "training.lessons.owner-rewards-oversight.step4": "ہر کوڈ بالکل اک واری کم کردا اے، تے کالعدم انعام کدے استعمال نہیں ہو سکدا — تریخ ہمیشہ دکھاندی اے کہ اک انعام کیہڑے پاسے مکا۔",
  "training.lessons.owner-rewards-oversight.title": "انعاماں دی نگرانی: تہاڈے مینیجر دا دینا",
  "training.lessons.staff-your-rewards.step1": "جدوں تہاڈا مینیجر یا مالک تہانوں اک انعام دیندا اے، تہاڈی گھنٹی وجدی اے۔ ورک فورس کھولو تے انعام تے ٹیپ کرو تاں اوہنوں میرے انعام دے تھلے ویکھو۔",
  "training.lessons.staff-your-rewards.step2": "ہر انعام دا اپنا کوڈ ہوندا اے۔ اوہنوں اپنے کول رکھو — جیہڑا ٹل تے کوڈ دکھاندا اے اوہی انعام استعمال کردا اے۔",
  "training.lessons.staff-your-rewards.step3": "اوہنوں استعمال کرن لئی، جدوں تسی خریدو تے کوڈ دکھاؤ۔ ٹل تے بندہ اوہنوں لکھدا اے تے استعمال شدہ نشان لاندا اے — ہر کوڈ بالکل اک واری کم کردا اے۔",
  "training.lessons.staff-your-rewards.step4": "انعام Business پلان دی دعوت نیں۔ جے تہاڈا سٹور Business تے نہیں، انعام ٹیب ایہدے بجائے اک بند دروازہ دکھاندی اے — اوہ پلان اے، کوئی غلطی نہیں۔",
  "training.lessons.staff-your-rewards.title": "تہاڈے انعام: اپنا کوڈ لبھنا تے اوہنوں استعمال کرنا",
