  "support.categoryLabel": "ایہہ کس بارے اے؟",
  "support.contextNote": "تاں اسیں مسئلہ لبھ سکیے، تہاڈا نوٹ خود بخود اوہ صفحہ شامل کردا اے جیہدے تے تسی او، جے کوئی چنیا گیا ہووے تے تہاڈا کاروبار تے کردار، تہاڈا پلان، تہاڈی ایپ دی بولی، تے تسی کیہڑی قسم دا فون یا براؤزر استعمال کر رہے او۔ ایہدے وچ کدے تہاڈے پروڈکٹ، سٹاک یا فروخت شامل نہیں ہوندے۔",
  "support.description": "کجھ خراب، کجھ غلط لگدا اے، یا سانجھا کرن لئی اک خیال؟ ایتھے سانوں دسو — تہاڈا نوٹ سدھا ایپ دے پچھے ٹیم کول جاندا اے۔",
  "support.errorGeneric": "ایہہ نہیں ہو سکیا۔ مہربانی کر کے دوبارہ کوشش کرو۔",
  "support.errorRateLimit": "تسی اج کئی رپورٹاں بھیجیاں نیں — شکریہ۔ مہربانی کر کے ہور بھیجن لئی کل تیک انتظار کرو، تاں ہر رپورٹ ٹھیک طرحاں پڑھی جا سکے۔",
  "support.errorTooLong": "ایہہ اوہدے توں لمبا اے جنا اک رپورٹ رکھ سکدی اے — مہربانی کر کے اوہنوں تھوڑا گھٹ کرو تے دوبارہ بھیجو۔",
  "support.errorTooShort": "مہربانی کر کے سانوں تھوڑا ہور دسو — اک یا دو جملے سانوں اوہنوں لبھن وچ مدد کردے نیں۔",
  "support.messageLabel": "کی ہویا؟",
  "support.messagePlaceholder": "سانوں دسو تسی کی کر رہے سی تے کی غلط ہویا، اپنے لفظاں وچ…",
  "support.sendAnother": "ہور رپورٹ بھیجو",
  "support.sending": "بھیجیا جا رہیا اے…",
  "support.sentBody": "اسیں ہر رپورٹ پڑھدے آں۔ جے سانوں ہور تفصیل چاہیدی ہوئی، اسیں تہاڈی اکاؤنٹ ای میل تے لکھاں گے۔",
  "support.sentTitle": "شکریہ — تہاڈی رپورٹ بھیج دتی گئی۔",
  "support.submit": "رپورٹ بھیجو",
  "support.title": "اک مسئلہ رپورٹ کرو",
  "support.urgentNote": "ایہدے بجائے اپنے اکاؤنٹ توں لاک آؤٹ ہو گئے او؟ تہاڈیاں فالتو چابیاں تہانوں واپس اندر لے جا سکدیاں نیں — اُتّے سیکیورٹی تے فالتو چابیاں ویکھو، یا سائن ان صفحے تے ریکوری دروازہ استعمال کرو۔",
  "training.lessons.mgr-report-problem.step1": "تہاڈی ٹیم ٹل تے کم کردی اے، جتھے مسئلے سب توں پہلاں ظاہر ہوندے نیں۔ جے ایپ تہاڈی ٹیم تے کسے لئی خراب ہو جاوے یا عجیب چلے، اوہنوں اوسے ویلے رپورٹ کیتا جا سکدا اے — اوہناں ولوں یا تہاڈے ولوں — سیٹنگاں توں، مسئلہ رپورٹ کرو دے تھلے۔",
  "training.lessons.mgr-report-problem.step2": "سادہ کہانی منگو: اوہ کی کر رہے سن، اوہناں نے کی توقع کیتی سی، تے ایہدے بجائے کی ہویا۔ اوہدا اک یا دو جملہ بعد وچ لکھی گئی کامل تفصیل توں ودھ قیمتی اے۔",
  "training.lessons.mgr-report-problem.step3": "رپورٹ اپنے آپ صفحہ، سٹور، بھیجن والے دا کردار، پلان، ایپ دی بولی تے ڈیوائس دی قسم منسلک کر دیندی اے؛ پروڈکٹ، سٹاک تے فروخت کدے منسلک نہیں ہوندے۔ سٹور دے نمبراں بارے کجھ وی رپورٹ نال نہیں جاندا۔",
  "training.lessons.mgr-report-problem.step4": "رپورٹاں ایپ دے پچھے ٹیم کول جاندیاں نیں تے ہر اک پڑھی جاندی اے۔ جے مسئلہ کسے نوں اوہناں دے اکاؤنٹ توں لاک آؤٹ کر دیوے، رپورٹ دا انتظار نہ کرو: فالتو چابیاں تے سائن ان صفحے دا ریکوری دروازہ اوہناں نوں واپس اندر لے جاندا اے۔",
  "training.lessons.mgr-report-problem.title": "جدوں تہاڈی ٹیم پھس جاوے: اوہنوں رپورٹ کرو، اوہدے آلے دوالے کم نہ کرو",
  "training.lessons.owner-report-problem.step1": "تہاڈی سبسکرپشن وچ اوہناں لوکاں نال سدھی لائن شامل اے جیہڑے ایس ایپ نوں بناندے نیں۔ سیٹنگاں کھولو تے مسئلہ رپورٹ کرو استعمال کرو — ایہہ ہر پلان تے اے، تہاڈے لئی تے تہاڈی ٹیم دے ہر ممبر لئی۔",
  "training.lessons.owner-report-problem.step2": "اپنے لفظاں وچ دسو کی ہویا: تسی کی کرن دی کوشش کر رہے سی، تے ایپ نے ایہدے بجائے کی کیتا۔ فارم ٹھیک کرن دیاں تفصیلاں — صفحہ، کاروبار، کردار، پلان، بولی تے ڈیوائس — اپنے آپ منسلک کر دیندا اے؛ تہاڈے پروڈکٹ، سٹاک تے فروخت کدے شامل نہیں ہوندے۔",
  "training.lessons.owner-report-problem.step3": "ہر رپورٹ محفوظ ہوندی اے تے ٹیم ولوں پڑھی جاندی اے۔ جے ہور تفصیل مدد کرے، اوہ اوس بندے دی اکاؤنٹ ای میل تے جواب دیندے نیں جیہنے اوہنوں بھیجیا سی — ایس لئی جواب اوس بندے کول پہنچدا اے جیہنے مسئلہ ویکھیا سی۔",
  "training.lessons.owner-report-problem.step4": "اک استثناء: جے تسی یا کوئی ٹیم ممبر اکاؤنٹ وچ بالکل نہیں جا سکدا، رپورٹ سب توں تیز دروازہ نہیں۔ فالتو چابیاں (سیٹنگاں، سیکیورٹی تے فالتو چابیاں) تے سائن ان صفحے تے ریکوری دروازہ بالکل اوہدے لئی موجود نیں۔",
  "training.lessons.owner-report-problem.title": "اک مسئلہ رپورٹ کرو: ایپ ٹیم نال تہاڈی سدھی لائن",
  "training.lessons.report-problem.step1": "جے ایپ وچ کجھ خراب ہو جاوے، غلط لگے، یا بس ٹھیک نہ لگے، تہانوں اوہدے نال نہیں رہنا پیندا۔ سیٹنگاں کھولو تے مسئلہ رپورٹ کرو لبھو — ایہہ ہر کسے لئی، ہر پلان تے موجود اے۔",
  "training.lessons.report-problem.step2": "چنو کہ تہاڈا نوٹ کس بارے اے — کجھ خراب اے، کجھ غلط لگدا اے، اک خیال، یا کجھ ہور — فیر اپنے لفظاں وچ لکھو کی ہویا۔ تسی کی کر رہے سی جدوں ایہہ ہویا اوہ سب توں ودھ مدد کردا اے۔",
  "training.lessons.report-problem.step3": "تہاڈا نوٹ خود بخود اوہ صفحہ لے جاندا اے جیہدے تے تسی سی، تہاڈا سٹور تے کردار، تہاڈا پلان، تہاڈی ایپ دی بولی، تے تسی کیہڑی قسم دا فون یا براؤزر استعمال کردے او — اوہ تفصیلاں جیہڑیاں مسئلہ لبھن وچ مدد کردیاں نیں۔ ایہہ کدے تہاڈے پروڈکٹ، سٹاک یا فروخت نہیں لے جاندا۔",
  "training.lessons.report-problem.step4": "اوہنوں بھیجو، تے اوہ سدھا ایپ دے پچھے ٹیم کول جاندا اے، جیہڑے ہر رپورٹ پڑھدے نیں۔ جے اوہناں نوں ہور تفصیل چاہیدی ہوئی، اوہ تہاڈی اکاؤنٹ ای میل تے لکھن گے۔ ایہدے بجائے اپنے اکاؤنٹ توں لاک آؤٹ ہو گئے او؟ اپنیاں فالتو چابیاں یا سائن ان صفحے تے ریکوری دروازہ استعمال کرو — اوہ رپورٹ توں تیز نیں۔",
  "training.lessons.report-problem.title": "اک مسئلہ رپورٹ کرو: جدوں کجھ خراب ہووے سانوں دسو",
