  "crossStore.transferIntro": "دونوں سٹور تواڈے نیں، اس لئی تساں بغیر کسی بینتی دے سٹاک سدھا بھیج سکدے او۔ اک پروڈکٹ چنو، دسو کِنّا تے کتھوں جاوے گا، تے اوہ سٹور چنو جتھے اوہ پہنچے گا۔ دونوں سٹور فوراً اپ ڈیٹ ہو جاندے نیں، تے دونوں اس بھیجن دا ریکارڈ رکھدے نیں۔",
