  "training.lessons.owner-move-stock.step1": "بینتیاں منگن لئی ہندیاں نیں؛ بھیجنا مالکاں دا کم ہے۔ کراس سٹور ان باکس صفحے تے، سٹاک بھیجو پینل تہانوں — مالک نوں — اس سٹور توں اپنے دوجے سٹور وچ بغیر بینتی تے بغیر انتظار دے سٹاک سدھا بھیجن دیندا ہے۔",
  "training.lessons.owner-move-stock.step2": "پروڈکٹ، اوہ تھاں جتھوں اوہ جاوے گا، تے مقدار چنو۔ ایپ دکھاندا ہے کہ اوس تھاں تے کِنّا موجود ہے، تے کوئی بھیجنا اوس توں وَدھ کدے نہیں لے سکدا۔",
  "training.lessons.owner-move-stock.step3": "منزل سٹور چنو، تے جے چاہو تے اوتھوں دی ٹھیک تھاں وی۔ جے اوس سٹور وچ پہلاں ای اوہی SKU ہووے، تے سٹاک اوس پروڈکٹ وچ رَل جاندا ہے؛ جے نہ ہووے، تے پروڈکٹ سٹاک سمیت کاپی ہو جاندا ہے۔",
  "training.lessons.owner-move-stock.step4": "دونوں سٹور ریکارڈ رکھدے نیں: ایہ سٹور باہر جان والی منتقلی دکھاندا ہے، دوجا وصولی دکھاندا ہے۔ جے بھیجنا ممکن نہ ہووے — کافی موجود نہ ہووے، یا دوجا سٹور تواڈا نہ ہووے — تے کجھ نہیں ہِلدا تے ایپ وجہ دسدا ہے۔",
