  "pricing.startLabel": "شروع",
  "training.lessons.mgr-pricing.step1": "Business تے، پروڈکٹ فارم وچ فروخت قیمت دا سیکشن ہوندا ہے۔ کلیئرنس اک مستقل کمی ہے — طے کرو تے ایہ رہندی ہے۔ رول بیک تاریخاں والی سیل ہے: رول بیک قیمت، شروع ہون دا دن تے ختم ہون دا دن طے کرو۔",
  "training.lessons.mgr-pricing.step2": "تہانوں عام قیمت کدے دوبارہ نہیں لکھنی پیندی: ایہ پروڈکٹ تے رہندی ہے تے پروڈکٹ فہرست تے سکینر وچ فروخت قیمت دے نال دکھدی ہے، تاں جو کوئی وی دیکھ سکے کہ چیز عام طور تے کنے دی ہے۔",
  "training.lessons.mgr-pricing.step3": "جدوں رول بیک شروع ہووے تاں تازہ قیمت لیبل چھاپو — لیبل اوہ قیمت چھاپدے نیں جو گاہک اوس دن دیندا ہے۔ جدوں ختم ہون دی تاریخ لنگھ جاوے، قیمت اپنے آپ عام تے واپس آ جاندی ہے؛ جدوں تساں شیلف تازہ کرو تاں عام لیبل دوبارہ چھاپو۔",
  "training.lessons.mgr-pricing.step4": "جے فروخت قیمت دا سیکشن بند دکھے، تے کاروبار Business منصوبے تے نہیں ہے — فروخت قیمت اوس منصوبے دی ہے، تے منصوبہ بدلن والے مالک ہوندے نیں۔",
  "training.lessons.mgr-pricing.title": "سیل چلانا: کلیئرنس تے رول بیک",
  "training.lessons.owner-pricing.step1": "پروڈکٹ فارم وچ، فروخت قیمت دے تحت، دو طراں دیاں کمیاں رہندیاں نیں۔ کلیئرنس مستقل ہے: کلیئرنس قیمت طے کرو تے ایہ اس وقت تک گھٹ رہندی ہے جب تک تساں اس نوں واپس نہ بدلو۔ رول بیک اک عارضی سیل ہے — شروع تے ختم تاریخاں نال اک گھٹ قیمت، وڈے سٹوراں توں تساں پہلاں ای جاندے او سیلاں وانگ۔",
  "training.lessons.owner-pricing.step2": "عام قیمت کدے مٹائی نہیں جاندی۔ جدوں رول بیک چلدا ہے، ایپ فروخت قیمت دے نال عام قیمت نال دکھاندا ہے، تے چھپے لیبل فروخت قیمت لے جاندے نیں، تاں جو شیلف تے کیش میل کھان۔",
  "training.lessons.owner-pricing.step3": "جدوں ختم ہون دی تاریخ لنگھ جاوے، قیمت اپنے آپ عام تے واپس آ جاندی ہے — کجھ یاد نہیں رکھنا، کجھ واپس نہیں کرنا۔ جو رول بیک اجے شروع نہیں ہویا، اوہ پروڈکٹ فہرست تے ای اپنی شروعات تاریخ دسدا ہے۔",
  "training.lessons.owner-pricing.step4": "فروخت قیمت Business منصوبے دی خصوصیت ہے۔ Essentials تے کھیت بند رہندے نیں، تے جے کوئی کاروبار Essentials تے جا کے واپس آوے، تے اوس دی کلیئرنس تے رول بیک سیٹنگ اوتھے ای رہندی ہے، بالکل جیویں چھڈی گئی سی۔",
  "training.lessons.owner-pricing.title": "کلیئرنس تے رول بیک قیمت (Business منصوبہ)",
